    if (typeof p.surpriseOutcomeQuality === "number") this._dispositions.surpriseOutcomeQuality = p.surpriseOutcomeQuality;
    if (typeof p.planBiasGain === "number") this._dispositions.planBiasGain = p.planBiasGain;
