            id: `step-${i}`,
            order: i,
            action: s.action,
            description: s.description,
            expectedOutcome: s.expectedOutcome,
            prerequisites: s.prerequisites ?? (i > 0 ? [`step-${i - 1}`] : []),
            estimatedDuration: s.estimatedDuration,
            status: "pending"
