      // engine-inferred at execute (emergent tier), not executive-set
      expectedOutcome: planData.expectedOutcome ?? "",
      createdAt: tick,
      requestingEntityId: goalState?.requestingEntityId,
      requestingThreadId: goalState?.requestingThreadId
